def cancel_order(
    db_path: str, tenant: str, order_id: str, version: int, approved: bool
) -> bool:
    """A write the model can only propose; the host runs it after human approval."""
    if not approved:
        raise PermissionError("Host approval required.")
    with closing(sqlite3.connect(db_path)) as db, db:
        cursor = db.execute(
            "UPDATE orders SET status = 'cancelled', version = version + 1"
            " WHERE tenant = ? AND id = ? AND version = ? AND status = 'pending'",
            (tenant, order_id, version),
        )
    return cursor.rowcount == 1

import hashlib
import hmac
import secrets
import time
from typing import Any

from claude_agent_sdk import (
    PermissionResultAllow,
    PermissionResultDeny,
    ToolPermissionContext,
)
from pydantic import BaseModel, ConfigDict


class Refund(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)
    order_id: str
    amount_cents: int

    def fingerprint(self) -> str:
        return hashlib.sha256(self.model_dump_json().encode()).hexdigest()


APPROVED: dict[
    str, tuple[str, float]
] = {}  # token -> (fingerprint, expiry); filled only by approve()


def approve(
    action: Refund, ttl: float = 120
) -> str:  # the human clicked; channels only notify
    token = secrets.token_urlsafe(32)
    APPROVED[token] = (action.fingerprint(), time.monotonic() + ttl)
    return token


async def gate(
    name: str, args: dict[str, Any], ctx: ToolPermissionContext
) -> PermissionResultAllow | PermissionResultDeny:
    wanted = (
        Refund.model_validate(args).fingerprint() if name == "mcp__shop__refund" else ""
    )
    for token, (bound, expires) in list(APPROVED.items()):
        if wanted and hmac.compare_digest(bound, wanted) and time.monotonic() < expires:
            del APPROVED[token]  # single use
            return PermissionResultAllow()
    return PermissionResultDeny(message="No live approval for this exact action.")

import csv
import json
from collections import defaultdict
from decimal import Decimal
from typing import Any

from claude_agent_sdk import ClaudeAgentOptions, create_sdk_mcp_server, tool


def totals_with_ledger(path: str) -> dict[str, Any]:
    totals: defaultdict[str, Decimal] = defaultdict(Decimal)
    ledger: list[str] = []
    with open(path, newline="", encoding="utf-8") as source:
        for row in csv.DictReader(source):
            totals[row["region"]] += Decimal(row["amount"])
            ledger.append(
                f"{row['region']} += {row['amount']} -> {totals[row['region']]}"
            )
    return {
        "totals": {region: str(value) for region, value in totals.items()},
        "ledger": ledger,
    }


def build_options(csv_path: str) -> ClaudeAgentOptions:
    @tool(
        "analyze_sales",
        "Return Python-computed sales totals by region and their ledger.",
        {},
    )
    async def analyze_sales(args: dict[str, Any]) -> dict[str, Any]:
        return {
            "content": [
                {"type": "text", "text": json.dumps(totals_with_ledger(csv_path))}
            ]
        }

    return ClaudeAgentOptions(
        tools=[],
        mcp_servers={
            "lesson": create_sdk_mcp_server(name="lesson", tools=[analyze_sales])
        },
        allowed_tools=["mcp__lesson__analyze_sales"],
